#!/usr/bin/env python3
"""Link the accepted and provisional boot C bodies into the complete boot.

This linking witness alone does not approve a match. The caller compiles the
hash-pinned C sources with privately held tools; all generated assembly,
non-code data and linked binaries remain under ignored build/.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import struct
from dataclasses import dataclass
from pathlib import Path

from boot_assembly import (DATA_SECTIONS, ROOT, TEXT_SIZE, TEXT_START,
                           render_data, text_words, verify_load_image)
from compare_boot_slice import compare
from elf import inspect_elf
from r5900_assembly import (ASSEMBLER_SHA256, LINKER_SHA256, check_tool,
                            render_assembly, run_tool)
from c_source_policy import require_c_source

OUTPUT = ROOT / "build/boot-c-campaign"

# Explicit, enumerated accepted set: one entry per promoted boot definition, in
# boot address order. A name here is a reviewed placement whose own compiled
# body supplies the complete function; only a verified ALIGN(8) zero word may
# follow it, and that word earns no C credit. Adding or removing an entry changes
# the counted scope and
# must be accompanied by a fresh complete-boot gate receipt and profile update.
