def source_path(name: str) -> Path:
    folder = "src/boot" if name in ACCEPTED_SOURCES else "nonmatching/boot"
    return ROOT / folder / f"{name}.c"


def accepted_replacements() -> tuple[Replacement, ...]:
    """Resolve the accepted set to campaign owners, in boot address order."""
    owners = tuple(item for item in REPLACEMENTS if item.name in ACCEPTED_SOURCES)
    missing = sorted(ACCEPTED_SOURCES - {item.name for item in owners})
    if missing:
        raise ValueError(f"accepted boot source has no campaign owner: {missing}")
    for item in owners:
        if not source_path(item.name).is_file():
            raise ValueError(f"accepted boot source is missing: {item.name}")
        if (ROOT / "nonmatching/boot" / f"{item.name}.c").exists():
            raise ValueError(
                f"accepted boot source is still staged in nonmatching/: {item.name}")
    return owners


RODATA_ADDRESS, RODATA_SIZE = next(
    (address, size) for name, address, size in DATA_SECTIONS if name == ".rodata")
BSS_START = 0x01F28100
BSS_SIZE = 817644
TRAIL_SIZE = 20
PREFIX_SIZE = 128


@dataclass(frozen=True)
class Replacement:
    name: str
    start: int
    end: int
    source_sha256: str
    object_sha256: str
    # Base address of the object's own .rodata, for a body whose constants the
    # retail code loads from the shared pool instead of materialising in place.
    # The campaign supplies the retail data sections from boot_data.o and
    # discards each replacement's .rodata, so such a body is pre-linked alone
    # (see prelink_pool_body) and only its resolved .text joins the campaign.
    pool: int | None = None
    # Same mechanism for a body that also carries initialised data (a table of
    # wide-character state, for instance): the object's .data is placed at the
    # measured retail base and its bytes are checked before the body is used.
    data: int | None = None


def object_digest_matches(item: Replacement, observed: str,
                          profile: dict[str, object]) -> bool:
    """Accept only measured whole-object hashes, including a pinned SN variant.

    Ps2EeAs has produced two otherwise identical objects for six sources. The
    second hash differs by one byte in non-loadable `.mdebug`; both still need
    the complete linked-program comparison before any C can count.
    """
    if observed == item.object_sha256:
        return True
    alternates = profile.get("object_sha256_alternates", {})
    return observed in alternates.get(item.name, ())


