def validate_replacements() -> None:
    """Each aligned boot interval has one named owner; no aliases of object paths."""
    names = [item.name for item in REPLACEMENTS]
    if len(set(names)) != len(names):
        raise ValueError("duplicate C interval owner")
    if any(not name or name in (".", "..") or "/" in name or "\\" in name for name in names):
        raise ValueError("C interval owners must be source basenames")
    if any(type(item.start) is not int or type(item.end) is not int
           or not TEXT_START + PREFIX_SIZE <= item.start < item.end <= TEXT_START + TEXT_SIZE
           or item.start % 8 or item.end % 8 for item in REPLACEMENTS):
        raise ValueError("C intervals lie outside aligned boot text")
    if any(left.end > right.start for left, right in zip(REPLACEMENTS, REPLACEMENTS[1:])):
        raise ValueError("C intervals overlap or are out of order")
    if any(item.pool is not None
           and (type(item.pool) is not int or item.pool % 4
                or not RODATA_ADDRESS <= item.pool < RODATA_ADDRESS + RODATA_SIZE)
           for item in REPLACEMENTS):
        raise ValueError("C interval pools must be 4-byte aligned inside the retail .rodata")


def check_inputs(objects_dir: Path) -> None:
    validate_replacements()
    profile = json.loads((ROOT / "config/boot/compiler_trial.json").read_text(
        encoding="utf-8"))
    for item in REPLACEMENTS:
        source = source_path(item.name)
        normalized = source.read_text(encoding="utf-8").replace("\r\n", "\n")
        require_c_source(normalized, item.name)
        if hashlib.sha256(normalized.encode("utf-8")).hexdigest() != item.source_sha256:
            raise ValueError(f"{item.name} source differs from measured trial")
        obj = objects_dir / f"{item.name}.o"
        if not object_digest_matches(
                item, hashlib.sha256(obj.read_bytes()).hexdigest(), profile):
            raise ValueError(f"{item.name} object differs from measured GNU EE trial")


def split_assembly(assembly: str) -> tuple[str, str, list[str]]:
    """Remove C intervals while preserving external branch labels by address."""
    lines = assembly.splitlines()
    header = [".set noat", ".set noreorder", ".section .text",
              ".globl boot_text_start", "boot_text_start:"]
    if lines[:len(header)] != header:
        raise ValueError("boot assembly header differs from measured layout")
    validate_replacements()
    prefix = [".set noat", ".set noreorder", ".section .text.align", ".align 7",
              ".globl boot_text_start", "boot_text_start:"]
    remainder = [".set noat", ".set noreorder"]
    address = TEXT_START
    current_segment = None
    skipped_labels: list[str] = []
    for line in lines[len(header):]:
        region = next((i for i, item in enumerate(REPLACEMENTS)
                       if item.start <= address < item.end), None)
        if region is None:
            if address < TEXT_START + PREFIX_SIZE:
                prefix.append(line)
            else:
                segment = sum(item.end <= address for item in REPLACEMENTS)
                if segment != current_segment:
                    remainder.append(f".section .text.seg{segment}")
                    current_segment = segment
                remainder.append(line)
        elif line.endswith(":"):
            label = line[:-1]
            if label != f"L_{address:08X}":
                raise ValueError(f"unexpected label inside C interval: {label}")
            skipped_labels.append(label)
        if line.startswith("    "):
            address += 4
    if (address != TEXT_START + TEXT_SIZE
            or sum(line.startswith("    ") for line in prefix) != PREFIX_SIZE // 4):
        raise ValueError("split assembly does not span measured boot text")
    return ("\n".join(prefix) + "\n", "\n".join(remainder) + "\n",
            skipped_labels)


def boot_data_slice(boot: Path, section_name: str, address: int, size: int) -> bytes:
    """Retail bytes at `address` inside a measured data section."""
    report = inspect_elf(boot)
    section = next(item for item in report["sections"] if item["name"] == section_name)
    base = int(section["virtual_address"], 16)
    if address < base or address + size > base + int(section["size"]):
        raise ValueError(f"{section_name} range 0x{address:08X}+{size} lies outside "
                         f"retail {section_name}")
    offset = int(section["file_offset"]) + address - base
    return boot.read_bytes()[offset:offset + size]


def object_function_size(path: Path, name: str) -> int:
    """Size of `name` in an ELF object's symbol table."""
    data = path.read_bytes()
    header = struct.Struct("<HHIIIIIHHHHHH")
    section = struct.Struct("<IIIIIIIIII")
    symbol = struct.Struct("<IIIBBH")
    (_, _, _, _, _, shoff, _, _, _, _, shentsize, shnum, _) = header.unpack_from(data, 16)
    headers = [section.unpack_from(data, shoff + index * shentsize)
               for index in range(shnum)]
    for _, kind, _, _, offset, size, link, _, _, entsize in headers:
        if kind != 2 or entsize != symbol.size or link >= shnum or headers[link][1] != 3:
            continue
        strings = data[headers[link][4]:headers[link][4] + headers[link][5]]
        for at in range(offset, offset + size, entsize):
            name_at, _, value_size, info, _, section_index = symbol.unpack_from(data, at)
            end = strings.index(b"\0", name_at)
            if strings[name_at:end].decode("ascii", "replace") == name:
                return value_size
    raise ValueError(f"{name}: no function symbol in {path.name}")


def prelink_pool_body(item: Replacement, linker: Path, assembler: Path,
                      boot: Path, output: Path) -> None:
    """Resolve one pool body's `.text` alone, then emit it as data words.

    The campaign takes the retail data sections from boot_data.o and discards
    every replacement's `.rodata`. A body whose constants are loaded from that
    pool therefore cannot be linked directly: its HI16/LO16 pairs would resolve
    against address 0, silently. Linking the body alone at its retail address,
    with `.rodata` pinned to the measured pool base, resolves those pairs to the
    retail addresses; the resulting `.text` carries no relocation, so it can be
    injected between the retail text segments as assembled words. The pool bytes
    are checked against the pinned boot before the body is accepted, and the
    function symbol keeps its compiled extent for the witness catalogue.
    """
    known: dict[str, str] = {}
    for line in LINKER_SYMBOLS:
        known[line.split(" = ")[0]] = line
    for other in REPLACEMENTS:
        line = f"{other.name} = 0x{other.start:08X};"
        if other.name in known and known[other.name] != line:
            raise ValueError(f"pool symbol disagrees with the linker script: {other.name}")
        known[other.name] = line
    script = [*known.values(), "SECTIONS {", f"  . = 0x{item.start:08X};",
              f"  .text : {{ {item.name}.o(.text) }}",
              f"  .rodata 0x{item.pool:08X} : {{ {item.name}.o(.rodata) }}"]
    if item.data is not None:
        script.append(f"  .data 0x{item.data:08X} : {{ {item.name}.o(.data) }}")
    script.append("}")
    (output / f"{item.name}.pool.ld").write_text("\n".join(script) + "\n",
                                                 encoding="ascii", newline="\n")
    run_tool([str(linker.resolve()), "-T", f"{item.name}.pool.ld", "-o",
              f"{item.name}.prelink.elf", f"{item.name}.o"],
             output, output / f"{item.name}.prelink.log")
    # ld.exe reports some layout errors and still exits 0, so the output file
    # and every address are checked instead of trusting the exit status.
    elf = output / f"{item.name}.prelink.elf"
    if not elf.is_file() or elf.stat().st_size == 0:
        raise ValueError(f"{item.name}: the pool pre-link wrote no ELF")
    report = inspect_elf(elf)
    text = next(section for section in report["sections"] if section["name"] == ".text")
    pool = next(section for section in report["sections"] if section["name"] == ".rodata")
    if (int(text["virtual_address"], 16) != item.start
            or int(pool["virtual_address"], 16) != item.pool
            or text["size"] % 4 or text["size"] > item.end - item.start):
        raise ValueError(f"{item.name}: pre-linked layout differs from the pinned interval")
    image = elf.read_bytes()
    pool_bytes = image[int(pool["file_offset"]):int(pool["file_offset"]) + pool["size"]]
    if pool_bytes != boot_data_slice(boot, ".rodata", item.pool, pool["size"]):
        raise ValueError(f"{item.name}: pre-linked pool differs from the pinned retail .rodata")
    if item.data is not None:
        data = next((section for section in report["sections"]
                     if section["name"] == ".data"), None)
        if data is None or int(data["virtual_address"], 16) != item.data:
            raise ValueError(f"{item.name}: pre-linked .data missing or misplaced")
        data_bytes = image[int(data["file_offset"]):int(data["file_offset"]) + data["size"]]
        if data_bytes != boot_data_slice(boot, ".data", item.data, data["size"]):
            raise ValueError(f"{item.name}: pre-linked .data differs from the pinned retail .data")
    body = image[int(text["file_offset"]):int(text["file_offset"]) + text["size"]]
    body_size = object_function_size(output / f"{item.name}.o", item.name)
    body = body[:body_size]
    source = [".set noat", ".section .text", f".globl {item.name}",
              f".ent {item.name}", f"{item.name}:"]
    source += [f"    .word 0x{int.from_bytes(body[at:at + 4], 'little'):08X}"
               for at in range(0, len(body), 4)]
    source.append(f".end {item.name}")
    (output / f"{item.name}.pooltext.s").write_text("\n".join(source) + "\n",
                                                    encoding="ascii", newline="\n")
    run_tool([str(assembler.resolve()), "-o", f"{item.name}.pooltext.o",
              f"{item.name}.pooltext.s"], output, output / f"{item.name}.pooltext.log")
    assembled = output / f"{item.name}.pooltext.o"
    if not assembled.is_file() or assembled.stat().st_size == 0:
        raise ValueError(f"{item.name}: the assembler wrote no pool object")


def linker_script(skipped_labels: list[str]) -> str:
    parts = ["boot_prefix_align.o(.text.align)"]
    for index, item in enumerate(REPLACEMENTS):
        body = (f"{item.name}.pooltext.o(.text)" if item.pool is not None
                else f"{item.name}.o(.text)")
        parts += [f"boot_split_multi.o(.text.seg{index})", body, ". = ALIGN(8);"]
    parts.append(f"boot_split_multi.o(.text.seg{len(REPLACEMENTS)})")
    lines = [*LINKER_SYMBOLS,
             *(f"{label} = 0x{label[2:]};" for label in skipped_labels),
             "SECTIONS {", f"  . = 0x{TEXT_START:08X};",
             "  .text : { " + " ".join(parts) + " }"]
    for name, address, _size in DATA_SECTIONS:
        lines.append(f"  . = 0x{address:08X}; {name} : {{ boot_data.o({name}) }}")
    lines += [f"  . = 0x{BSS_START:08X}; .bss : {{ boot_bss.o(.bss) }}",
              "  .tail (NOLOAD) : { boot_tail.o(.tail) }"]
    # A compiled body substitutes `.text` only: the retail's data sections come
    # from boot_data.o. Three libm bodies still emit an unreferenced `.rodata`
    # (the fdlibm constants, which -G0 materialises inside the body instead), and
    # an orphan section would be placed on top of the retail `.rodata`. Discard
    # exactly those objects' sections so the retail data keeps its addresses.
    # A pool body never joins the link as an object: only its pre-linked
    # `.pooltext.o` does, and that object carries no data section.
    discard = " ".join(f"{item.name}.o(.rodata)" for item in REPLACEMENTS
                       if item.pool is None)
    lines.append(f"  /DISCARD/ : {{ {discard} }}")
    lines.append("}")
    return "\n".join(lines) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("boot", type=Path)
    parser.add_argument("--objects-dir", type=Path, required=True)
    parser.add_argument("--assembler", type=Path, required=True)
    parser.add_argument("--linker", type=Path, required=True)
    args = parser.parse_args()
    check_tool(args.assembler, ASSEMBLER_SHA256)
    check_tool(args.linker, LINKER_SHA256)
    check_inputs(args.objects_dir)
    target = json.loads((ROOT / "config/target.json").read_text(encoding="utf-8"))
    words = text_words(args.boot, target["boot_sha256"])
    assembly, stats = render_assembly(words, TEXT_START, symbol="boot_text_start",
                                      raw_cop1_branches=True)
    if (stats["sqrt_s"] != 50 or stats["cop1_branch_words"] != 6
            or stats["zero_target_jumps"] or stats["instructions"] != TEXT_SIZE // 4):
        raise ValueError("rendered boot assembly differs from measured baseline")
    prefix, remainder, labels = split_assembly(assembly)
    data_source, _ = render_data(args.boot)
    OUTPUT.mkdir(parents=True, exist_ok=True)
    for name, source in (("boot_prefix_align.s", prefix),
                         ("boot_split_multi.s", remainder),
                         ("boot_data.s", data_source),
                         ("boot_bss.s", f".section .bss\n.space {BSS_SIZE}\n"),
                         ("boot_tail.s", f'.section .tail,"aw",@nobits\n.space {TRAIL_SIZE}\n')):
        (OUTPUT / name).write_text(source, encoding="ascii", newline="\n")
    (OUTPUT / "boot_multi.ld").write_text(linker_script(labels),
                                           encoding="ascii", newline="\n")
    for item in REPLACEMENTS:
        (OUTPUT / f"{item.name}.o").write_bytes(
            (args.objects_dir / f"{item.name}.o").read_bytes())
    for stem in ("boot_prefix_align", "boot_split_multi", "boot_data",
                 "boot_bss", "boot_tail"):
        run_tool([str(args.assembler.resolve()), "-o", f"{stem}.o", f"{stem}.s"],
                 OUTPUT, OUTPUT / f"{stem}.log")
    for item in REPLACEMENTS:
        if item.pool is not None:
            prelink_pool_body(item, args.linker, args.assembler, args.boot, OUTPUT)
    run_tool([str(args.linker.resolve()), "-N", "-e", "0x01E62508",
              "-T", "boot_multi.ld", "-o",
              "boot_multi.elf", "boot_prefix_align.o", "boot_split_multi.o",
              *((f"{item.name}.pooltext.o" if item.pool is not None
                 else f"{item.name}.o") for item in REPLACEMENTS),
              "boot_data.o", "boot_bss.o", "boot_tail.o"],
             OUTPUT, OUTPUT / "linker.log")
    candidate = OUTPUT / "boot_multi.elf"
    exact, count, digest = compare(args.boot, candidate, TEXT_START, TEXT_SIZE,
                                   target["boot_sha256"])
    if not exact:
        raise ValueError(f"C-linked boot text differs: {count}/{TEXT_SIZE} bytes equal")
    load_digest = verify_load_image(args.boot, candidate)
    reference = inspect_elf(args.boot)
    linked = inspect_elf(candidate)
    expected_program = next(item for item in reference["programs"] if item["type"] == 1)
    actual_program = next(item for item in linked["programs"] if item["type"] == 1)
    expected_raw = args.boot.read_bytes()[expected_program["file_offset"]:
                                          expected_program["file_offset"] + expected_program["file_size"]]
    actual_raw = candidate.read_bytes()[actual_program["file_offset"]:
                                        actual_program["file_offset"] + actual_program["file_size"]]
    expected_bss = next(item for item in reference["sections"] if item["name"] == ".bss")
    actual_bss = next(item for item in linked["sections"] if item["name"] == ".bss")
    tail = next(item for item in linked["sections"] if item["name"] == ".tail")
    if (linked["entry"] != reference["entry"]
            or actual_program != expected_program or actual_raw != expected_raw
            or actual_bss["virtual_address"] != expected_bss["virtual_address"]
            or actual_bss["size"] != expected_bss["size"] or actual_bss["type"] != 8
            or tail["type"] != 8 or tail["size"] != TRAIL_SIZE
            or int(tail["virtual_address"], 16) != BSS_START + BSS_SIZE):
        raise ValueError("C-linked entry/PT_LOAD/BSS layout or raw bytes differ from retail")
    print(f"C-linked boot .text: {count}/{TEXT_SIZE} exact; SHA-256 {digest}")
    print(f"C-linked raw PT_LOAD: {len(expected_raw)}/{len(expected_raw)} exact; "
          f"SHA-256 {load_digest}")
    print(f"ELF entry, PT_LOAD header and BSS: exact; {len(labels)} external code labels restored")
    print(f"{len(REPLACEMENTS)} compiled C objects linked into the boot; "
          f"{len(ACCEPTED_SOURCES)} selected for boot-only acceptance pending "
          "the complete gate; the rest are provisional witnesses")


if __name__ == "__main__":
    main()
